/*
  Generate the volume kernels for collisionless gyrokinetic terms.

  The functions called in this file are in gkFuncs-vol.mac.
*/
load("gyrokinetic/gk_collisionless/dg_gk-vol.mac")$

/* ...... USER INPUTS........ */

/* Serendipity basis. */
minPolyOrder_Ser : 1$
maxPolyOrder_Ser : 1$
minCdim_Ser : 1$
maxCdim_Ser : 3$

/* Tensor order basis. No need to generate p=1. */
minPolyOrder_Tensor : 2$
maxPolyOrder_Tensor : 2$
minCdim_Tensor : 1$
maxCdim_Tensor : 0$

/* Vdim possibilities for each of Cdim=[1,2,3]. */
gkVdims : [[1,2], [2], [2]]$

/* ...... END OF USER INPUTS........ */

/* To generate other bases, just add corresponding column to arrays below. */
bName        : ["ser", "tensor"]$
minPolyOrder : [minPolyOrder_Ser, minPolyOrder_Tensor]$
maxPolyOrder : [maxPolyOrder_Ser, maxPolyOrder_Tensor]$
minCdim      : [minCdim_Ser, minCdim_Tensor]$
maxCdim      : [maxCdim_Ser, maxCdim_Tensor]$

/* Possible combinations of variable dependence of background magnetic field.
   with [] = const. Note that we assume axisymmetry, which means B cannot depend on y. */
bVarsList : [x,z]$

/* Generate kernels of selected types. */
for bInd : 1 thru length(bName) do (
  for c : minCdim[bInd] thru maxCdim[bInd] do (
    for gkV : 1 thru length(gkVdims[c]) do (
      v : gkVdims[c][gkV],

      maxPolyOrderB : maxPolyOrder[bInd],
      if (c=3) then maxPolyOrderB : 1, /* Only generate p=1 kernels for 3x2v */
      for polyOrder : minPolyOrder[bInd] thru maxPolyOrderB do (
        fname : sconcat("~/max-out/dg_gyrokinetic_vol_", c, "x", v, "v_", bName[bInd], "_p", polyOrder, ".c"),
        disp(printf(false,"Creating volume file: ~a",fname)),

        fh : openw(fname),
        printf(fh, "#include <gkyl_dg_gyrokinetic_kernels.h> ~%"),

        funcName : sconcat("dg_gyrokinetic_vol_", c, "x", v, "v_", bName[bInd], "_p", polyOrder),
        buildGKVolKernel(fh, funcName, c, v, bName[bInd], polyOrder, bVarsList, false),
        close(fh),

        /* if cdim > 1, also generate a set of kernels for the case where there is no toroidal field (by = 0) */
        if (c > 1) then (
          fname : sconcat("~/max-out/dg_gyrokinetic_no_by_vol_", c, "x", v, "v_", bName[bInd], "_p", polyOrder, ".c"),
          disp(printf(false,"Creating volume file (no by): ~a",fname)),

          fh : openw(fname),
          printf(fh, "#include <gkyl_dg_gyrokinetic_kernels.h> ~%"),

          funcName : sconcat("dg_gyrokinetic_no_by_vol_", c, "x", v, "v_", bName[bInd], "_p", polyOrder),
          buildGKVolKernel(fh, funcName, c, v, bName[bInd], polyOrder, bVarsList, true),
          close(fh)
        )
      )
    )
  )
)$
/* Compute the header file for gyrokinetic collisionless equation object kernels. */

/* ...... USER INPUTS........ */

/* Serendipity basis. */
maxPolyOrder_Ser : 2$
minCdim_Ser : 1$
minVdim_Ser : 1$
maxCdim_Ser : 3$
maxVdim_Ser : 2$

/* Tensor order basis. */
maxPolyOrder_Tensor : 2$
minCdim_Tensor : 1$
minVdim_Tensor : 1$
maxCdim_Tensor : 0$
maxVdim_Tensor : 0$

/* Number of velocity dimensions allowed for each
   configuration-space dimension. */
gkVdims : [[1,2], [2], [2]]$

/* ...... END OF USER INPUTS........ */

varsC : [x, y, z]$
varsV : [vpar, mu]$

/* To generate other bases, just add corresponding column to arrays below. */
bName        : ["ser", "tensor"]$
maxPolyOrder : [maxPolyOrder_Ser, maxPolyOrder_Tensor]$
minCdim      : [minCdim_Ser, minCdim_Tensor]$
minVdim      : [minVdim_Ser, minVdim_Tensor]$
maxCdim      : [maxCdim_Ser, maxCdim_Tensor]$
maxVdim      : [maxVdim_Ser, maxVdim_Tensor]$

printPrototypes() := block([],
  for bInd : 1 thru length(bName) do (
    for c : minCdim[bInd] thru maxCdim[bInd] do (
      for gkV : 1 thru length(gkVdims[c]) do (
        v : gkVdims[c][gkV],

        maxPolyOrderB : maxPolyOrder[bInd],
        if (c=3) then maxPolyOrderB : 1, /* Only declare p=1 kernels for 3x2v */
        for polyOrder : 1 thru maxPolyOrderB do (

          printf(fh, "GKYL_CU_DH double dg_gyrokinetic_vol_~ax~av_~a_p~a(const double *w, const double *dxv,
            const double *vmap, const double *vmapSq, const double q_, const double m_,
            const double *bmag, const double *phi,
            const double *dualcurlbhatoverB, const double *rtg33inv, const double* bioverJB,
            const double *fin, double* GKYL_RESTRICT out); ~%", c, v, bName[bInd], polyOrder),
          printf(fh, "GKYL_CU_DH double dg_gyrokinetic_no_by_vol_~ax~av_~a_p~a(const double *w, const double *dxv,
            const double *vmap, const double *vmapSq, const double q_, const double m_,
            const double *bmag, const double *phi,
            const double *dualcurlbhatoverB, const double *rtg33inv, const double* bioverJB,
            const double *fin, double* GKYL_RESTRICT out); ~%", c, v, bName[bInd], polyOrder),

          for surfDir : 1 thru c+1 do (
            if surfDir<=c then (
              dirlabel : varsC[surfDir]
            ) else (
              dirlabel : varsV[surfDir-c]
            ),

            if surfDir<=c then (
              extraargs : "const struct gkyl_dg_surf_geom *dgs, const struct gkyl_gk_dg_surf_geom *gkdgs, "
            ) else (
              extraargs : "const struct gkyl_dg_vol_geom *dgv, const struct gkyl_gk_dg_vol_geom *gkdgv, "
            ),

            if surfDir<=c then (
              vprimeargs : ""
            ) else (
              vprimeargs : "const double *vmap_prime_l, const double *vmap_prime_r, "
            ),

            printf(fh, "GKYL_CU_DH double dg_gyrokinetic_surf~a_~ax~av_~a_p~a(const double *w, const double *dxv,
              const double *vmap_prime_l, const double *vmap_prime_c, const double *vmap_prime_r, 
              const double *flux_surf_l, const double *flux_surf_r, 
              double* GKYL_RESTRICT out); ~%", dirlabel, c, v, bName[bInd], polyOrder),
            printf(fh, "GKYL_CU_DH double dg_gyrokinetic_boundary_surf~a_~ax~av_~a_p~a(const double *w, const double *dxv,
              const double *vmap_prime_edge, const double *vmap_prime_skin, 
              const double *flux_surf_edge, const double *flux_surf_skin, 
              const int edge, double* GKYL_RESTRICT out); ~%", dirlabel, c, v, bName[bInd], polyOrder)
          ),
          printf(fh, "~%")
/*
   Create kernels for the volume term of the gyrokinetic collisionless terms.
*/

load("core/modal-basis.mac")$
load("util_maxima/out-scripts.mac")$
load(stringproc)$
load("scifac")$
load("gyrokinetic/utilities_gyrokinetic.mac")$
load("util_maxima/utilities.mac")$
fpprec : 24$

